#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <iostream>
#include <utility>
#include <vector>

using namespace std;

constexpr int MOD = 1000000007;

struct Point {
    int x;
    int y;
};

static int mod_pow(int base, int exponent) {
    long long result = 1;
    long long value = base;
    while (exponent > 0) {
        if (exponent & 1) result = result * value % MOD;
        value = value * value % MOD;
        exponent >>= 1;
    }
    return static_cast<int>(result);
}

static int choose_mod(int total, int selected,
                      const vector<int>& factorial,
                      const vector<int>& inverse_factorial) {
    long long result = factorial[total];
    result = result * inverse_factorial[selected] % MOD;
    result = result * inverse_factorial[total - selected] % MOD;
    return static_cast<int>(result);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<pair<int, int>> blocked;
    blocked.reserve(static_cast<size_t>(m));
    for (int c = 0; c < m; ++c) {
        int row, col;
        cin >> row >> col;
        blocked.emplace_back(row, col);
    }

    sort(blocked.begin(), blocked.end());
    blocked.erase(unique(blocked.begin(), blocked.end()), blocked.end());

    const pair<int, int> start{0, 0};
    const pair<int, int> target{n - 1, n - 1};
    if (binary_search(blocked.begin(), blocked.end(), start) ||
        binary_search(blocked.begin(), blocked.end(), target)) {
        cout << 0 << '\n';
        return 0;
    }

    const uint64_t point_count = static_cast<uint64_t>(blocked.size()) + 1;
    const uint64_t sparse_pairs = point_count * (point_count - 1) / 2;
    const uint64_t grid_cells = static_cast<uint64_t>(n) * n;

    if (sparse_pairs <= grid_cells / 12) {
        vector<Point> points;
        points.reserve(blocked.size() + 1);
        for (const auto& cell : blocked) {
            points.push_back({cell.second, cell.first});
        }
        points.push_back({n - 1, n - 1});
        sort(points.begin(), points.end(), [](const Point& a, const Point& b) {
            const int sum_a = a.x + a.y;
            const int sum_b = b.x + b.y;
            if (sum_a != sum_b) return sum_a < sum_b;
            if (a.x != b.x) return a.x < b.x;
            return a.y < b.y;
        });

        const int max_sum = 2 * (n - 1);
        vector<int> factorial(max_sum + 1);
        vector<int> inverse_factorial(max_sum + 1);
        factorial[0] = 1;
        for (int i = 1; i <= max_sum; ++i) {
            factorial[i] = static_cast<long long>(factorial[i - 1]) * i % MOD;
        }
        inverse_factorial[max_sum] = mod_pow(factorial[max_sum], MOD - 2);
        for (int i = max_sum; i > 0; --i) {
            inverse_factorial[i - 1] =
                static_cast<long long>(inverse_factorial[i]) * i % MOD;
        }

        vector<int> ways(points.size(), 0);
        const int* factorial_data = factorial.data();
        const int* inverse_factorial_data = inverse_factorial.data();
        for (size_t i = 0; i < points.size(); ++i) {
            const Point& p = points[i];
            const int total = p.x + p.y;
            int value = choose_mod(total, p.x, factorial, inverse_factorial);
            uint64_t sum = 0;
            const Point* point_data = points.data();
            const int* ways_data = ways.data();
#if defined(_OPENMP)
#pragma omp simd reduction(+:sum)
#endif
            for (size_t j = 0; j < i; ++j) {
                const Point& q = point_data[j];
                if (q.x <= p.x && q.y <= p.y) {
                    const int dx = p.x - q.x;
                    const int dy = p.y - q.y;
                    long long paths =
                        static_cast<long long>(factorial_data[dx + dy]) *
                        inverse_factorial_data[dx] % MOD;
                    paths = paths * inverse_factorial_data[dy] % MOD;
                    sum += static_cast<uint64_t>(ways_data[j]) *
                           static_cast<uint64_t>(paths) % MOD;
                }
            }
            value -= static_cast<int>(sum % MOD);
            if (value < 0) value += MOD;
            ways[i] = value;
        }

        cout << ways.back() << '\n';
        return 0;
    }

    vector<int> dp(n, 0);
    size_t block_index = 0;
    for (int row = 0; row < n; ++row) {
        size_t row_end = block_index;
        while (row_end < blocked.size() && blocked[row_end].first == row) {
            ++row_end;
        }
        size_t next_block = block_index;
        for (int col = 0; col < n; ++col) {
            if (next_block < row_end && blocked[next_block].second == col) {
                dp[col] = 0;
                ++next_block;
            } else if (row == 0 && col == 0) {
                dp[col] = 1;
            } else {
                int value = dp[col];
                if (col > 0) value += dp[col - 1];
                if (value >= MOD) value -= MOD;
                dp[col] = value;
            }
        }
        block_index = row_end;
    }

    cout << dp[n - 1] << '\n';
    return 0;
}
